import requests
import pdfplumber
import io

url = "https://www.mospi.gov.in/sites/default/files/publication_reports/AnnualReport_PLFS2023-24L2.pdf"
response = requests.get(url)

with pdfplumber.open(io.BytesIO(response.content)) as pdf:
    for i, page in enumerate(pdf.pages):
        text = page.extract_text()
        if text and i > 20:
            tl = text.lower()
            if "state/ut" in tl or "statement" in tl:
                if "unemployment rate" in tl or "table" in tl:
                    # check for state names
                    if "kerala" in tl or "nagaland" in tl or "bihar" in tl:
                        print(f"Page {i+1}: {text[:200].replace(chr(10), ' ')}")
